import{_ as s,l as n,o as e,c as i,v as r,p,x as t,d as l,i as d,S as c}from"./chunks/framework.InCnrqk-.js";const T=JSON.parse('{"title":"trapframe","description":"","frontmatter":{"title":"trapframe","date":"2026-09-08T00:00:00.000Z","section":"cs"},"headers":[],"relativePath":"cs/trapframe.md","filePath":"cs/trapframe.md","lastUpdated":1789023840000}'),m={name:"cs/trapframe.md"};function f(h,a,E,_,A,u){const o=n("Mermaid");return e(),i("div",null,[a[1]||(a[1]=r('<h1 id="trapframe" tabindex="-1">trapframe <a class="header-anchor" href="#trapframe" aria-label="Permalink to &quot;trapframe&quot;">​</a></h1><div class="epigraph"><p>陷入必须把用户可见的寄存器收进内核栈上的一帧，返回时原样写回；否则用户程序会在随机寄存器里醒来。</p><footer>—— 据 Tanenbaum and Bos, Modern Operating Systems；Bovet and Cesati 整理</footer></div><p><a href="/cs/vdso">上一课</a>让部分查询免陷入。一旦执行陷入指令或发生异常、中断，<a href="/cs/exception-interrupt-entry">异常入口</a>会切特权并跳到固定向量。缺口是：硬件只保证保存 PC 与原因；<strong>通用寄存器、用户栈指针、返回后的特权级</strong>要由软件收成一份可恢复的帧——trapframe。本课只钉这帧，不走系统调用分发。</p><h2 id="问题" tabindex="-1">问题 <a class="header-anchor" href="#问题" aria-label="Permalink to &quot;问题&quot;">​</a></h2><p>用户线程的 <code>a0</code>–<code>a7</code> 里可能正是系统调用参数，也可能是被中断的普通计算。若内核随手用这些寄存器当临时量，返回用户时计算已坏。跨线程切换还要把帧与<a href="/cs/process-image">进程映像</a>里的其余状态接上。缺口不是新的环，而是内核栈顶那块<strong>与 ISA 寄存器一一对应的内存映像</strong>。</p><p>本课不把每一种架构的 <code>pt_regs</code> 字段表背完。</p><p><span class="marginnote">trapframe 通常压在该线程的内核栈上。切换线程时换内核栈指针，等于换到另一份帧。用户栈指针是帧里的一个字段，不是内核正在用的栈。</span></p><h2 id="方法" tabindex="-1">方法 <a class="header-anchor" href="#方法" aria-label="Permalink to &quot;方法&quot;">​</a></h2><p>入口：硬件或极短汇编保存 PC、状态寄存器，再把通用寄存器写入帧；内核 C 代码只通过帧读写用户状态。返回：按帧恢复，执行 <code>sret</code>/<code>iret</code>，特权降回用户。系统调用的返回值写入帧中的返回值槽，再走同一条恢复路径。中断与自愿陷入共用帧布局，便于同一套返回代码。</p>',9)),(e(),p(c,null,{default:t(()=>[d(o,{id:"mermaid-25",class:"mermaid",graph:"flowchart%20TD%0A%20%20TRAP%5B%22%E9%99%B7%E5%85%A5%E6%88%96%E4%B8%AD%E6%96%AD%22%5D%20--%3E%20SAVE%5B%22%E5%86%99%E5%85%A5%20trapframe%22%5D%0A%20%20SAVE%20--%3E%20K%5B%22%E5%86%85%E6%A0%B8%E7%94%A8%E5%B8%A7%E8%AF%BB%E5%86%99%E7%94%A8%E6%88%B7%E5%AF%84%E5%AD%98%E5%99%A8%22%5D%0A%20%20K%20--%3E%20REST%5B%22%E6%8C%89%E5%B8%A7%E6%81%A2%E5%A4%8D%E5%B9%B6%E8%BF%94%E5%9B%9E%22%5D%0A"})]),fallback:t(()=>[...a[0]||(a[0]=[l(" Loading... ",-1)])]),_:1})),a[2]||(a[2]=r('<p><a href="/cs/calling-convention-stack">调用约定</a>的用户栈帧仍在用户页上；本课的对象是内核里那份架构状态副本。</p><h2 id="机制" tabindex="-1">机制 <a class="header-anchor" href="#机制" aria-label="Permalink to &quot;机制&quot;">​</a></h2><p>有了帧，内核可以在处理过程中调度：当前线程的用户寄存器不在 CPU 上，而在它的 trapframe 里。<a href="/cs/context-switch">上下文切换</a>换的是「哪份帧成为活的」，不另造一套寄存器含义。缺页、系统调用、设备 IRQ 都先落到同一形状的帧，再按原因分发——分发是下一课路径。</p><p>内核自己的调用用内核栈上的普通帧，不要与 trapframe 混名。本课只要求：凡从用户来，先有 trapframe。</p><h2 id="边界" tabindex="-1">边界 <a class="header-anchor" href="#边界" aria-label="Permalink to &quot;边界&quot;">​</a></h2><p>本课不写 FPU 惰性保存的全部 ABI，不把信号递送如何改用户 PC 提前讲完。也不讨论调试器改帧里的寄存器——那是更后的跟踪课。安全课关心「有没有漏存」；本课假定保存完整。</p><p>后课默认：进入内核时用户状态在 trapframe 里。用户按 ABI 请求服务之后，如何按号分发、拷贝参数、返回，下一课走<a href="/cs/syscall-path">系统调用路径</a>。</p><h2 id="小结" tabindex="-1">小结 <a class="header-anchor" href="#小结" aria-label="Permalink to &quot;小结&quot;">​</a></h2><ul><li>trapframe 是内核栈上的用户寄存器映像；返回必须按它恢复。</li><li>中断与系统调用共用帧布局；切换换的是哪份帧活着。</li><li>分发与参数拷贝是路径课的缺口。</li><li>出处：Tanenbaum and Bos, <em>MOS</em>；Bovet and Cesati。</li></ul>',9))])}const P=s(m,[["render",f]]);export{T as __pageData,P as default};
